mapper.select:
select c.id, c.user_id, c.target_type, c.target_id, c.parent_id, c.content, c.like_count, c.create_time, u.nickname, u.avatar_url, case c.target_type when 'attraction' then a.name when 'guide' then g.title end as target_title, pc.content as parent_content, pu.nickname as parent_nickname from voya_ai_comment c left join voya_ai_user u on c.user_id = u.id left join voya_ai_attraction a on c.target_type = 'attraction' and c.target_id = a.id left join voya_ai_guide g on c.target_type = 'guide' and c.target_id = g.id left join voya_ai_comment pc on c.parent_id > 0 and pc.id = c.parent_id left join voya_ai_user pu on pc.user_id = pu.id
c.del_flag = '0'
and c.target_type = #{targetType}
and u.nickname like concat('%', #{nickname}, '%')
and c.content like concat('%', #{keyword}, '%')
and c.parent_id > 0
and c.parent_id = #{parentId}
and c.create_time >= #{beginCreateTime}
and c.create_time < date_add(#{endCreateTime}, interval 1 day)
order by c.create_time desc, c.id desc

select count(*) from voya_ai_comment
where id = #{parentId} and target_type = #{targetType} and target_id = #{targetId}
  and parent_id = 0 and del_flag = '0'

mapper.update:
update voya_ai_attraction
set comment_count = greatest(0, ifnull(comment_count, 0) + #{delta})
where id = #{targetId}

update voya_ai_guide
set comment_count = greatest(0, ifnull(comment_count, 0) + #{delta})
where id = #{targetId}
